function query({ startDate, endDate, market }) {
  const d = /^\d{4}\/\d{2}\/\d{2}$/;
  if (!d.test(startDate) || !d.test(endDate) || startDate > endDate)
    throw Error("Enter dates as YYYY/MM/DD, start no later than end");
  if (typeof market !== "string") throw Error("Invalid market");
  return {
    url:
      "https://data.moa.gov.tw/api/v1/SheepQuotation/?Start_time=" +
      encodeURIComponent(startDate) +
      "&End_time=" +
      encodeURIComponent(endDate),
    market,
  };
}

const x = query({ startDate: "2024/12/01", endDate: "2024/12/31", market: "" });
return [{ json: { ...x, spreadsheetId: "YOUR_SPREADSHEET_ID", sheetName: "Sheet1" } }];

function rows({ body, market }) {
  if (!body || body.RS !== "OK" || !Array.isArray(body.Data) || body.Next !== false)
    throw Error("Sheep quotation response incomplete or invalid");
  const fields = [
    "transDate",
    "marketID",
    "shortName",
    "name",
    "productID",
    "productName",
    "productTypeName",
    "quantity",
    "avgWeight",
    "avgPrice",
    "highestPrice",
    "Record_ID",
  ];
  const values = body.Data.filter((x) => !market || x.shortName === market).map((x) => {
    if (!x || typeof x !== "object") throw Error("Invalid quotation");
    return fields.map((f) => {
      if (typeof x[f] !== "string" && typeof x[f] !== "number")
        throw Error("Missing quotation field: " + f);
      return x[f];
    });
  });
  return { values, hasRows: values.length > 0 };
}

const x = rows({
  body: $input.first().json,
  market: $("Choose the dates and market").first().json.market,
});
return x.values.map((v) => ({
  json: Object.fromEntries(
    [
      "transDate",
      "marketID",
      "shortName",
      "name",
      "productID",
      "productName",
      "productTypeName",
      "quantity",
      "avgWeight",
      "avgPrice",
      "highestPrice",
      "Record_ID",
    ].map((k, i) => [k, v[i]]),
  ),
}));
